<?php require 'config.php';login_required();$admin=$_SESSION['user']['role']==='admin';$msg=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{
if(in_array($a,['add','edit'])){$n=trim($_POST['name']??'');$d=trim($_POST['description']??'');$q=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$p=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);if(!$n||$q===false||$q<0||$p===false||$p<0)throw new Exception('Enter valid product details.');if($a==='add'){$s=$pdo->prepare('INSERT INTO products(name,description,quantity,price,created_by) VALUES(?,?,?,?,?)');$s->execute([$n,$d,$q,$p,$_SESSION['user']['id']]);$msg='Product added.';}else{$s=$pdo->prepare('UPDATE products SET name=?,description=?,quantity=?,price=? WHERE id=?');$s->execute([$n,$d,$q,$p,(int)$_POST['id']]);$msg='Product updated.';}}
elseif($a==='delete'){$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([(int)$_POST['id']]);$msg='Product deleted.';}
elseif(in_array($a,['approve','reject'])&&$admin){$s=$pdo->prepare("UPDATE users SET status=? WHERE id=? AND role='user'");$s->execute([$a==='approve'?'approved':'rejected',(int)$_POST['id']]);$msg='User status updated.';}
}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$products=$pdo->query('SELECT p.*,u.username creator FROM products p LEFT JOIN users u ON u.id=p.created_by ORDER BY p.id DESC')->fetchAll();
$pending=$admin?$pdo->query("SELECT * FROM users WHERE status='pending' AND role='user' ORDER BY id")->fetchAll():[];
$users=$admin?$pdo->query('SELECT id,username,status,role,created_at FROM users ORDER BY id DESC')->fetchAll():[];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Inventory System</title><link rel="stylesheet" href="assets/style.css"></head><body><header><b>▣ Inventory System</b><span><?=e($_SESSION['user']['username'])?> · <?=e($admin?'Admin':'User')?>　<a href="logout.php">Logout</a></span></header><main class="wrap"><h1>Dashboard</h1><p>Manage products and inventory records.</p><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?>
<?php if($admin):?><section><h2>Pending registrations</h2><?php if(!$pending):?><p>No pending users.</p><?php else:?><div class="scroll"><table><tr><th>Username</th><th>Registered</th><th>Action</th></tr><?php foreach($pending as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['created_at'])?></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button name="action" value="approve">Approve</button><button class="red" name="action" value="reject">Reject</button></form></td></tr><?php endforeach;?></table></div><?php endif;?><h2>Users</h2><div class="scroll"><table><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
<section><h2><?=$edit?'Edit product':'Add product'?></h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><label>Product name<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Description<input name="description" value="<?=e($edit['description']??'')?>"></label><label>Quantity<input type="number" min="0" name="quantity" required value="<?=e($edit['quantity']??0)?>"></label><label>Price<input type="number" min="0" step=".01" name="price" required value="<?=e($edit['price']??'0.00')?>"></label><button><?=$edit?'Save changes':'Add product'?></button><?php if($edit):?><a href="dashboard.php">Cancel</a><?php endif;?></form></section>
<section><h2>Products (<?=count($products)?>)</h2><div class="scroll"><table><tr><th>Name</th><th>Description</th><th>Quantity</th><th>Price</th><th>Created by</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['description'])?></td><td><?=e($p['quantity'])?></td><td>₱<?=number_format((float)$p['price'],2)?></td><td><?=e($p['creator']??'—')?></td><td><a href="?edit=<?=$p['id']?>">Edit</a> <form class="inline" method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="red" name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table></div></section><p class="foot">Activity #1 Final Term · Inventory System</p></main></body></html>